/**
 * Signs release builds with a real key instead of the debug one.
 *
 * Expo's generated `build.gradle` points `buildTypes.release` at
 * `signingConfigs.debug` and leaves a comment telling you not to ship that.
 * The `android/` directory is regenerated by every `prebuild`, so editing it by
 * hand loses the change — this plugin re-applies it each time.
 *
 * The keystore and its passwords come from the environment and never enter the
 * repository (NFR-S-08). With none set, the build falls back to Expo's default,
 * so a contributor without the key can still build and run locally.
 *
 *   ANDROID_KEYSTORE_PATH      absolute path to the .keystore
 *   ANDROID_KEYSTORE_PASSWORD
 *   ANDROID_KEY_ALIAS
 *   ANDROID_KEY_PASSWORD       defaults to the store password
 */
const { withAppBuildGradle } = require('@expo/config-plugins');

const SIGNING_CONFIG = 'fitnessRelease';

function injectSigningConfig(contents, options) {
  // Gradle reads the keystore path relative to android/app, so an absolute
  // path is used and its separators normalised for the Groovy string.
  const storeFile = options.keystorePath.replace(/\\/g, '/');

  const config = `
        ${SIGNING_CONFIG} {
            storeFile file('${storeFile}')
            storePassword System.getenv("ANDROID_KEYSTORE_PASSWORD")
            keyAlias System.getenv("ANDROID_KEY_ALIAS")
            keyPassword System.getenv("ANDROID_KEY_PASSWORD") ?: System.getenv("ANDROID_KEYSTORE_PASSWORD")
        }
`;

  let next = contents;

  // Add the config alongside the debug one.
  if (!next.includes(SIGNING_CONFIG)) {
    next = next.replace(/(signingConfigs\s*\{)/, `$1\n${config}`);
  }

  // Point the release build type at it. The comment above the line is Expo's
  // warning about the debug key, which no longer applies.
  next = next.replace(
    /(release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/,
    `$1signingConfig signingConfigs.${SIGNING_CONFIG}`,
  );

  return next;
}

module.exports = function withReleaseSigning(config) {
  const keystorePath = process.env.ANDROID_KEYSTORE_PATH;
  if (!keystorePath) return config;

  return withAppBuildGradle(config, (gradleConfig) => {
    if (gradleConfig.modResults.language !== 'groovy') {
      throw new Error('withReleaseSigning expects a Groovy build.gradle');
    }
    gradleConfig.modResults.contents = injectSigningConfig(gradleConfig.modResults.contents, {
      keystorePath,
    });
    return gradleConfig;
  });
};
